import{_ as a,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"45. 使用 fgets 和 fputs 进行缓冲 I/O","description":"The Little Book of C 中文版 — 45. 使用 fgets 和 fputs 进行缓冲 I/O","frontmatter":{"title":"45. 使用 fgets 和 fputs 进行缓冲 I/O","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","05-输入输出与文件","中文"],"description":"The Little Book of C 中文版 — 45. 使用 fgets 和 fputs 进行缓冲 I/O","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":45,"sidebarWeight":45,"alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/045-Buffered IO with fgets and fputs","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/045-Buffered IO with fgets and fputs"},"headers":[],"relativePath":"posts/c教程/zh-CN/05-输入输出与文件/045-Buffered IO with fgets and fputs.md","filePath":"posts/c教程/zh-CN/05-输入输出与文件/045-Buffered IO with fgets and fputs.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/05-输入输出与文件/045-Buffered IO with fgets and fputs.md"};function i(l,s,o,c,d,u){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>[English version](/posts/c教程/en-US/05-Input Output and Files/045-Buffered IO with fgets and fputs)</p><p>当您的程序读取和写入数据时，它并不总是直接进入磁盘或终端，而是使用缓冲区。缓冲区是临时保存数据的小内存块，通过减少系统执行缓慢 I/O 操作的频率来提高性能。</p><p>C 的标准 I/O 库（<code>&lt;stdio.h&gt;</code>）会自动为您处理此问题。在本节中，您将了解缓冲的工作原理以及如何使用<code>fgets</code>,<code>fputs</code>，以及有效管理它的相关功能。</p><h4 id="什么是缓冲-i-o" tabindex="-1">什么是缓冲 I/O？ <a class="header-anchor" href="#什么是缓冲-i-o" aria-label="Permalink to &quot;什么是缓冲 I/O？&quot;">​</a></h4><p>C 库不是一次读取或写入一个字符，而是：</p><ul><li>填充缓冲区（用于输入）或</li><li>收集一批字符（用于输出）</li></ul><p>当缓冲区已满或刷新时，数据在程序和文件或终端之间移动。</p><p>这就是为什么有时<code>printf()</code>输出不会立即出现，它会在缓冲区中等待，直到发生换行或刷新。</p><h4 id="输入-fgets" tabindex="-1">输入：fgets() <a class="header-anchor" href="#输入-fgets" aria-label="Permalink to &quot;输入：fgets()&quot;">​</a></h4><p><code>fgets()</code>从流中读取整行（包括空格）并将其存储在字符串中。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char *fgets(char *str, int size, FILE *stream);</span></span></code></pre></div><p>-<code>str</code>：存储线的位置 -<code>size</code>：读取的最大字符数（包括<code>\\0</code>) -<code>stream</code>：从哪里读取（例如<code>stdin</code>或文件指针）</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char line[100];</span></span>
<span class="line"><span>    printf(&quot;Enter a sentence: &quot;);</span></span>
<span class="line"><span>    if (fgets(line, sizeof(line), stdin))</span></span>
<span class="line"><span>        printf(&quot;You said: %s&quot;, line);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C is beautiful.</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You said: C is beautiful.</span></span></code></pre></div><p>如果输入超出缓冲区，<code>fgets</code>之后停止阅读<code>size - 1</code>字符以防止溢出，并自动以空值终止字符串。</p><h4 id="输出-fputs" tabindex="-1">输出：fputs() <a class="header-anchor" href="#输出-fputs" aria-label="Permalink to &quot;输出：fputs()&quot;">​</a></h4><p><code>fputs()</code>将字符串写入流。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int fputs(const char *str, FILE *stream);</span></span></code></pre></div><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;output.txt&quot;, &quot;w&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Open failed&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fputs(&quot;Buffered I/O makes C fast.\\n&quot;, fp);</span></span>
<span class="line"><span>    fputs(&quot;fgets and fputs are line-based tools.\\n&quot;, fp);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    printf(&quot;Wrote to output.txt\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Buffered I/O makes C fast.</span></span>
<span class="line"><span>fgets and fputs are line-based tools.</span></span></code></pre></div><h4 id="为什么-fgets-比-scanf-s-更安全" tabindex="-1">为什么 fgets 比 scanf(&quot;%s&quot;, …) 更安全 <a class="header-anchor" href="#为什么-fgets-比-scanf-s-更安全" aria-label="Permalink to &quot;为什么 fgets 比 scanf(&quot;%s&quot;, …) 更安全&quot;">​</a></h4><p>-<code>fgets()</code>尊重缓冲区边界</p><ul><li>它可以正确读取空格和制表符</li><li>它可以防止溢出的未定义行为</li></ul><p>避免这种情况：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scanf(&quot;%s&quot;, buffer); // stops at first space and may overflow</span></span></code></pre></div><p>更喜欢这个：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fgets(buffer, sizeof(buffer), stdin);</span></span></code></pre></div><h4 id="使用-fputs-写入-stdout-或-stderr" tabindex="-1">使用 fputs 写入 stdout 或 stderr <a class="header-anchor" href="#使用-fputs-写入-stdout-或-stderr" aria-label="Permalink to &quot;使用 fputs 写入 stdout 或 stderr&quot;">​</a></h4><p><code>fputs()</code>适用于任何输出流，而不仅仅是文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fputs(&quot;Message to screen.\\n&quot;, stdout);</span></span>
<span class="line"><span>fputs(&quot;Error to stderr!\\n&quot;, stderr);</span></span></code></pre></div><p>您甚至可以在 shell 中重定向它们：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &gt; result.txt 2&gt; error.log</span></span></code></pre></div><h4 id="逐行读取文件" tabindex="-1">逐行读取文件 <a class="header-anchor" href="#逐行读取文件" aria-label="Permalink to &quot;逐行读取文件&quot;">​</a></h4><p>以下是如何使用以下方法安全地读取文件<code>fgets()</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;poem.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Failed to open file&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char line[200];</span></span>
<span class="line"><span>    while (fgets(line, sizeof(line), fp))</span></span>
<span class="line"><span>        printf(&quot;%s&quot;, line);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="小代码-复制文件" tabindex="-1">小代码：复制文件 <a class="header-anchor" href="#小代码-复制文件" aria-label="Permalink to &quot;小代码：复制文件&quot;">​</a></h4><p>一个最小的文件复制器使用<code>fgets</code>和<code>fputs</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *in = fopen(&quot;input.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    FILE *out = fopen(&quot;copy.txt&quot;, &quot;w&quot;);</span></span>
<span class="line"><span>    if (!in || !out) {</span></span>
<span class="line"><span>        perror(&quot;File error&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char buf[256];</span></span>
<span class="line"><span>    while (fgets(buf, sizeof(buf), in))</span></span>
<span class="line"><span>        fputs(buf, out);</span></span>
<span class="line"><span>    fclose(in);</span></span>
<span class="line"><span>    fclose(out);</span></span>
<span class="line"><span>    printf(&quot;Copied successfully.\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="缓冲液冲洗" tabindex="-1">缓冲液冲洗 <a class="header-anchor" href="#缓冲液冲洗" aria-label="Permalink to &quot;缓冲液冲洗&quot;">​</a></h4><p>有时您需要手动刷新输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fflush(stdout);</span></span></code></pre></div><p>这对于必须立即显示消息的交互式程序非常有用。</p><p>要完全禁用缓冲（例如，用于日志记录）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setbuf(stdout, NULL);</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>缓冲 I/O 平衡速度和安全性：</p><p>-<code>fgets</code>防止溢出 -<code>fputs</code>确保高效输出</p><ul><li>缓冲最大限度地减少缓慢的磁盘和控制台调用</li></ul><p>这使得 C 既低级又高性能，而无需强迫您自己管理每个字节。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个程序，从 stdin 读取行并将其写入新文件。</li><li>计算在 EOF 之前读了多少行。</li><li>使用以下命令打印每一行的行号<code>fgets</code>和<code>printf</code>.</li><li>试验缓冲区大小，尝试 16 与 256 字节并注意性能差异。</li><li>在交互式日志记录程序的每一行之后刷新输出。</li></ol><p><code>fgets</code>和<code>fputs</code>为您的文件和控制台 I/O 提供安全、基于行的基础。接下来，您将学习如何使用正确处理错误<code>errno</code>,<code>perror</code>， 和<code>strerror</code>，用 C 语言编写可靠系统程序的基本工具。</p>`,58)])])}const f=a(t,[["render",i]]);export{h as __pageData,f as default};
